import 'package:flutter/material.dart';import 'package:modulos/core/theme/app_colors.dart';import 'package:modulos/core/widgets/responsive_layout.dart';class DashboardScreen extends StatefulWidget {  final int selectedNav;  final ValueChanged<int> onNavSelect;  const DashboardScreen({super.key, required this.selectedNav, required this.onNavSelect});  @override  State<DashboardScreen> createState() => _DashboardScreenState();}class _DashboardScreenState extends State<DashboardScreen> {  @override  Widget build(BuildContext context) {    return ResponsiveLayout(      selectedNav: widget.selectedNav,      onNavSelect: widget.onNavSelect,      title: 'Dashboard',      contentBuilder: (context, constraints) => _buildContent(),    );  }  Widget _buildContent() {    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      children: [        _buildStatsGrid(constraints: null),      ],    );  }  Widget _buildStatsGrid({BoxConstraints? constraints}) {    return LayoutBuilder(      builder: (context, boxConstraints) {        final width = boxConstraints.maxWidth;        int crossAxisCount;        if (width >= 1100) {          crossAxisCount = 4;        } else if (width >= 700) {          crossAxisCount = 3;        } else {          crossAxisCount = 2;        }        return GridView.count(          shrinkWrap: true,          physics: const NeverScrollableScrollPhysics(),          crossAxisCount: crossAxisCount,          crossAxisSpacing: 16,          mainAxisSpacing: 16,          children: [            _buildStatCard('Clientes', '150', Icons.groups_rounded, AppColors.brandGreen),            _buildStatCard('Productos', '89', Icons.inventory_2_rounded, Colors.blue),            _buildStatCard('Ventas Hoy', '12', Icons.point_of_sale_rounded, Colors.orange),            _buildStatCard('Citas', '5', Icons.calendar_today_rounded, Colors.purple),          ],        );      },    );  }  Widget _buildStatCard(String title, String value, IconData icon, Color color) {    return Container(      padding: const EdgeInsets.all(20),      decoration: BoxDecoration(        color: AppColors.cardBg,        borderRadius: BorderRadius.circular(16),        border: Border.all(color: AppColors.cardBorder),      ),      child: Column(        crossAxisAlignment: CrossAxisAlignment.start,        mainAxisAlignment: MainAxisAlignment.spaceBetween,        children: [          Icon(icon, color: color, size: 32),          Column(            crossAxisAlignment: CrossAxisAlignment.start,            children: [              Text(value, style: const TextStyle(fontSize: 28, fontWeight: FontWeight.bold, color: AppColors.textPrimary)),              const SizedBox(height: 4),              Text(title, style: const TextStyle(color: AppColors.textSecondary)),            ],          ),        ],      ),    );  }}